// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(address actor, uint256 blockSeed) public {
        vm.assume(actor != address(0) && actor != address(c));
        // pick a block number divisible by 15 so the payout branch triggers
        uint256 bn = bound(blockSeed, 1, type(uint256).max / 15) * 15;
        vm.roll(bn);
        vm.warp(bn + 1); // timestamp must exceed pastBlockTime (initially 0)

        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok,) = address(c).call{value: 10 ether}("");
        assertTrue(ok);

        // Reference: payout branch fired, contract sent its whole balance to the caller.
        // Mutant: no transfer, balance stays 10 ether.
        assertTrue(address(c).balance == 0, "contract should have paid out its balance");
    }
}
